import { Mesh, PlaneGeometry, Object3D, Color } from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/tsl';
import { gsap } from 'gsap';
import { createText } from '@/text';

export default function createNode(config, ctx) {
  // ---------- Geometry ----------
  const geometry = new PlaneGeometry(1, 1);
  geometry.translate(0, 0, 0);

  // ---------- Texture ----------
  const texture = ctx.textureLoader.load(config.assets?.imageUrl ?? '');

  // ---------- Material ----------
  const material = new MeshBasicNodeMaterial({
    map: texture,
    side: DoubleSide,
    transparent: true,
  });

  // ---------- Mesh ----------
  const plane = new Mesh(geometry, material);
  plane.position.set(
    config.scenePlacement?.position?.[0] ?? 0,
    config.scenePlacement?.position?.[1] ?? 0,
    config.scenePlacement?.position?.[2] ?? 0,
  );
  plane.rotation.set(
    config.scenePlacement?.rotation?.[0] ?? 0,
    config.scenePlacement?.rotation?.[1] ?? 0,
    config.scenePlacement?.rotation?.[2] ?? 0,
  );
  plane.scale.set(
    config.scenePlacement?.scale?.[0] ?? 1,
    config.scenePlacement?.scale?.[1] ?? 1,
    config.scenePlacement?.scale?.[2] ?? 1,
  );

  // ---------- Text ----------
  let textObject = null;
  if (config.textContent) {
    const textColor = new Color(config.palette?.ink ?? '#16161d');
    textObject = createText({
      text: config.textContent,
      fontAtlas: ctx.fontAtlas,
      size: 0.34, // headline scale approximation
      color: textColor,
      // optional alignment and positioning within the card
      anchor: { x: 0, y: 0 },
    });
    // Slightly offset in front of the plane to avoid z‑fighting
    textObject.position.set(0, 0, 0.001);
    plane.add(textObject);
  }

  // ---------- Handlers ----------
  plane.userData.handlers = {};

  // ---------- Cleanup ----------
  const timelines = [];
  plane.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (texture) texture.dispose();
    if (textObject && textObject.dispose) textObject.dispose();
    timelines.forEach((tl) => tl.kill());
  };

  return plane;
}
